"use client";
import { Button } from "./button";
// Extracted leaf mechanics from Syuze MemoirBook: independent paper/board
// profiles, shared angle shading, cover-centering and release velocity.
import {
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type PointerEvent,
} from "react";
import { springFrames } from "./spring-frames";
import "./page-book.css";
export interface BookPage {
  id: string;
  content: ReactNode;
}
export interface PageBookProps {
  title: string;
  pages: BookPage[];
  cover?: ReactNode;
  coverColor?: string;
  className?: string;
  style?: CSSProperties;
  onPageChange?: (page: number) => void;
}
export function PageBook({
  title,
  pages,
  cover,
  coverColor = "var(--roc-accent, #64735f)",
  className = "",
  style,
  onPageChange,
}: PageBookProps) {
  const root = useRef<HTMLDivElement>(null),
    book = useRef<HTMLDivElement>(null),
    busy = useRef(false),
    anims = useRef<Animation[]>([]),
    generation = useRef(0);
  const [width, setWidth] = useState(500),
    [turned, setTurned] = useState(0),
    [moving, setMoving] = useState(false);
  const position = useRef(0);
  const spread = width >= 440,
    W = Math.max(80, Math.min(220, spread ? (width - 40) / 2 : width - 70)),
    H = W / 0.72,
    last = Math.ceil(pages.length / (spread ? 2 : 1));
  const live = useRef({ spread, W, last });
  live.current = { spread, W, last };
  const leaf = (i: number) =>
    root.current?.querySelector<HTMLElement>(`[data-leaf="${i}"]`);
  const shift = (angle: number) =>
    live.current.spread ? (-live.current.W / 2) * (1 + angle / 180) : 0;
  const rest = () => {
    for (let i = 0; i <= live.current.last; i++) {
      const el = leaf(i);
      if (!el) continue;
      const flipped = i < position.current;
      el.style.transform = flipped ? "rotateY(-180deg)" : "none";
      el.style.zIndex = String(flipped ? i + 1 : live.current.last + 2 - i);
      el.querySelectorAll<HTMLElement>(".roc-book-shade").forEach(
        (n) => (n.style.opacity = "0"),
      );
    }
    if (book.current)
      book.current.style.transform = `translateX(${position.current === 0 ? shift(0) : 0}px)`;
  };
  const pose = (i: number, angle: number) => {
    const el = leaf(i);
    if (!el) return;
    el.style.zIndex = "1000";
    el.style.transform = `rotateY(${angle}deg)`;
    el.querySelectorAll<HTMLElement>(".roc-book-shade").forEach(
      (n) =>
        (n.style.opacity = String(
          Math.sin((Math.abs(angle) * Math.PI) / 180) * 0.26,
        )),
    );
    if (i === 0 && book.current)
      book.current.style.transform = `translateX(${shift(angle)}px)`;
  };
  const settle = async (i: number, from: number, to: number, velocity = 0) => {
    const el = leaf(i);
    if (!el) return;
    const token = ++generation.current;
    busy.current = true;
    setMoving(true);
    pose(i, from);
    const mass = i === 0 ? 0.85 : 0.5,
      k = i === 0 ? 80 : 150;
    const samples = springFrames(
        { a: from },
        { a: to },
        { a: velocity },
        { stiffness: k, mass, damping: 2 * Math.sqrt(k * mass) },
      ),
      duration = samples.at(-1)!.time * 1000;
    if (!matchMedia("(prefers-reduced-motion: reduce)").matches) {
      const tracks = [
        { el, paint: (a: number) => ({ transform: `rotateY(${a}deg)` }) },
        ...[...el.querySelectorAll<HTMLElement>(".roc-book-shade")].map(
          (el) => ({
            el,
            paint: (a: number) => ({
              opacity: Math.sin((Math.abs(a) * Math.PI) / 180) * 0.26,
            }),
          }),
        ),
        ...(i === 0 && book.current
          ? [
              {
                el: book.current,
                paint: (a: number) => ({
                  transform: `translateX(${shift(a)}px)`,
                }),
              },
            ]
          : []),
      ];
      anims.current = tracks.map((t) =>
        t.el.animate(
          samples.map((s) => ({
            ...t.paint(s.values.a),
            offset: (s.time * 1000) / duration,
          })),
          { duration, easing: "linear", fill: "both" },
        ),
      );
      let timer: ReturnType<typeof setTimeout> | undefined;
      await Promise.race([
        Promise.all(anims.current.map((a) => a.finished.catch(() => {}))),
        new Promise((r) => {
          timer = setTimeout(r, duration + 100);
        }),
      ]);
      clearTimeout(timer);
    }
    if (token !== generation.current) return;
    rest();
    anims.current.forEach((a) => a.cancel());
    anims.current = [];
    busy.current = false;
    setMoving(false);
  };
  const step = (dir: number) => {
    if (busy.current) return;
    const i = dir > 0 ? position.current : position.current - 1;
    if (i < 0 || i > last) return;
    position.current += dir;
    setTurned(position.current);
    onPageChange?.(position.current);
    void settle(i, dir > 0 ? 0 : -180, dir > 0 ? -180 : 0);
  };
  const drag = useRef<{
    i: number;
    forward: boolean;
    x: number;
    angle: number;
    moved: boolean;
    trail: { x: number; t: number }[];
  } | null>(null);
  const down = (e: PointerEvent) => {
    if (
      busy.current ||
      (e.target as HTMLElement).closest("button,a,input,textarea,audio")
    )
      return;
    const r = book.current!.getBoundingClientRect(),
      forward = e.clientX >= r.left + (spread ? r.width / 2 : W * 0.35),
      i = forward ? position.current : position.current - 1;
    if (i < 0 || i > last) return;
    drag.current = {
      i,
      forward,
      x: e.clientX,
      angle: forward ? 0 : -180,
      moved: false,
      trail: [{ x: e.clientX, t: performance.now() }],
    };
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const move = (e: PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    const dx = e.clientX - d.x;
    if (!d.moved && Math.abs(dx) < 6) return;
    d.moved = true;
    d.angle = Math.max(
      -180,
      Math.min(
        0,
        (d.forward ? 0 : -180) + (180 * dx) / (W * (spread ? 1.4 : 1)),
      ),
    );
    d.trail.push({ x: e.clientX, t: performance.now() });
    if (d.trail.length > 5) d.trail.shift();
    pose(d.i, d.angle);
  };
  const up = (cancel = false) => {
    const d = drag.current;
    drag.current = null;
    if (!d) return;
    if (cancel) {
      void settle(d.i, d.angle, d.forward ? 0 : -180);
      return;
    }
    if (!d.moved) {
      step(d.forward ? 1 : -1);
      return;
    }
    const a = d.trail[0],
      b = d.trail.at(-1)!,
      velocity =
        b.t > a.t && performance.now() - b.t < 100
          ? (((180 * (b.x - a.x)) / (b.t - a.t)) * 1000) /
            (W * (spread ? 1.4 : 1))
          : 0,
      flipped = d.angle + velocity * 0.12 < -90;
    if (d.forward === flipped) {
      position.current += d.forward ? 1 : -1;
      setTurned(position.current);
      onPageChange?.(position.current);
    }
    void settle(d.i, d.angle, flipped ? -180 : 0, velocity);
  };
  useLayoutEffect(() => {
    const observer = new ResizeObserver((entries) =>
      setWidth(entries[0].contentRect.width),
    );
    observer.observe(root.current!);
    return () => {
      observer.disconnect();
      generation.current++;
      anims.current.forEach((a) => a.cancel());
    };
  }, []);
  useLayoutEffect(() => {
    generation.current++;
    anims.current.forEach((a) => a.cancel());
    anims.current = [];
    drag.current = null;
    busy.current = false;
    setMoving(false);
    position.current = Math.min(position.current, last + 1);
    setTurned(position.current);
    rest();
  }, [spread, W, last]);
  return (
    <div
      ref={root}
      className={`roc-page-book ${className}`}
      data-mode={spread ? "spread" : "single"}
      tabIndex={0}
      aria-label={`${title}, page-turning book`}
      style={
        {
          "--book-w": `${W}px`,
          "--book-h": `${H}px`,
          "--book-color": coverColor,
          ...style,
        } as CSSProperties
      }
      onKeyDown={(e) => {
        if (
          (e.target as HTMLElement).closest("input,textarea,[contenteditable]")
        )
          return;
        if (["ArrowLeft", "ArrowRight"].includes(e.key)) {
          e.preventDefault();
          e.stopPropagation();
          step(e.key === "ArrowRight" ? 1 : -1);
        }
      }}
    >
      <div
        className="roc-book-stage"
        onPointerDown={down}
        onPointerMove={move}
        onPointerUp={() => up()}
        onPointerCancel={() => up(true)}
      >
        <div ref={book} className="roc-book">
          {Array.from({ length: last + 1 }, (_, i) => {
            const front = spread ? (i - 1) * 2 : i - 1,
              back = spread ? front + 1 : -1;
            return (
              <div key={i} data-leaf={i} className="roc-book-leaf">
                <div
                  className={`roc-book-face front ${i === 0 ? "cover" : ""}`}
                  inert={i !== turned}
                  aria-hidden={i !== turned}
                >
                  {i === 0
                    ? (cover ?? <h3>{title}</h3>)
                    : pages[front]?.content}
                  <span className="roc-book-shade" />
                </div>
                <div
                  className={`roc-book-face back ${i === 0 ? "cover" : ""}`}
                  inert={!spread || i !== turned - 1}
                  aria-hidden={!spread || i !== turned - 1}
                >
                  {i === 0 ? (
                    <small>{title}</small>
                  ) : back >= 0 ? (
                    pages[back]?.content
                  ) : null}
                  <span className="roc-book-shade" />
                </div>
              </div>
            );
          })}
        </div>
      </div>
      <div className="roc-book-controls">
        <Button variant="ghost" size="sm"
          type="button"
          aria-label="Previous page"
          disabled={moving || turned === 0}
          onClick={() => step(-1)}
        >
          ←
        </Button>
        <span role="status">
          {turned === 0 ? "Cover" : `${turned} / ${last + 1}`}
        </span>
        <Button variant="ghost" size="sm"
          type="button"
          aria-label="Next page"
          disabled={moving || turned > last}
          onClick={() => step(1)}
        >
          →
        </Button>
      </div>
    </div>
  );
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Button as AnimatedButton } from "@animate-ui/react/primitives/buttons/button";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = AnimatedButton;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: var(--roc-space-2, 8px);
  min-height: var(--roc-control-height, 36px);
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-button-radius, var(--roc-radius-control));
  font-family: var(--roc-font-control, inherit);
  font-weight: var(--roc-weight-control, 500);
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
/* Keep the shared .roc-ui font reset from changing text button height. */
.roc-ui.roc-ui-button {
  line-height: 1.2;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
