import { sampleSpring, type SpringOptions } from "./physical-spring";
/** Vector spring samples; settle by position AND speed, then commit an exact destination. */
export function springFrames(
  from: Record<string, number>,
  to: Record<string, number>,
  velocity: Record<string, number> = {},
  options: Partial<SpringOptions> & { fps?: number } = {},
) {
  const fps = options.fps || 120,
    frames = [],
    keys = Object.keys(to);
  let quiet = 0;
  // WAAPI interpolates linearly between samples. A coarse initial segment would
  // visibly discard incoming speed during a high-acceleration reversal.
  const times = [
    ...new Set([
      0,
      0.001,
      0.002,
      0.004,
      ...Array.from({ length: fps * 4 }, (_, i) => (i + 1) / fps),
    ]),
  ].sort((a, b) => a - b);
  for (const time of times) {
    const values: Record<string, number> = {},
      speeds: Record<string, number> = {};
    let resting = true;
    for (const key of keys) {
      const s = sampleSpring(
        from[key],
        to[key],
        velocity[key] || 0,
        time,
        options,
      );
      values[key] = s.position;
      speeds[key] = s.velocity;
      const tolerance = key.startsWith("s")
        ? 0.0001
        : key === "angle"
          ? 0.0001
          : 0.03;
      resting &&=
        Math.abs(s.position - to[key]) < tolerance &&
        Math.abs(s.velocity) < tolerance * 10;
    }
    frames.push({ time, values, velocity: speeds });
    quiet = resting ? quiet + 1 : 0;
    if (quiet >= 3) break;
  }
  const last = frames.at(-1)!;
  last.values = { ...to };
  last.velocity = Object.fromEntries(keys.map((key) => [key, 0]));
  return frames;
}

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
export interface SpringOptions {
  stiffness: number;
  damping: number;
  mass: number;
}
export const DEFAULT_SPRING: SpringOptions = {
  stiffness: 400,
  damping: 38,
  mass: 1,
};
// Typed port of the retained legacy analytic spring; legacy source stays unchanged.
export function sampleSpring(
  from: number,
  to: number,
  velocity: number,
  seconds: number,
  options: Partial<SpringOptions> = {},
) {
  const {
    stiffness: k,
    damping: c,
    mass: m,
  } = { ...DEFAULT_SPRING, ...options };
  if (!(k > 0 && m > 0 && c >= 0))
    throw new RangeError("Invalid spring parameters");
  const t = Math.max(0, seconds),
    a = c / (2 * m),
    w2 = k / m,
    d = from - to;
  let x, v;
  if (Math.abs(a * a - w2) < 1e-7) {
    const b = velocity + a * d,
      e = Math.exp(-a * t);
    x = (d + b * t) * e;
    v = (b - a * (d + b * t)) * e;
  } else if (a * a < w2) {
    const w = Math.sqrt(w2 - a * a),
      b = (velocity + a * d) / w;
    const e = Math.exp(-a * t),
      cos = Math.cos(w * t),
      sin = Math.sin(w * t);
    x = e * (d * cos + b * sin);
    v = e * ((b * w - a * d) * cos - (d * w + a * b) * sin);
  } else {
    const q = Math.sqrt(a * a - w2),
      r1 = -a + q,
      r2 = -a - q;
    const b1 = (velocity - r2 * d) / (r1 - r2),
      b2 = d - b1;
    x = b1 * Math.exp(r1 * t) + b2 * Math.exp(r2 * t);
    v = r1 * b1 * Math.exp(r1 * t) + r2 * b2 * Math.exp(r2 * t);
  }
  return { position: to + x, velocity: v };
}

export type ContainerMotion =
  | "unfold"
  | "refold"
  | "pullReturn"
  | "dropGather"
  | "dropSink"
  | "lidOpen"
  | "lidClose";
/** Same parameter families as legacy src/spring.js; deterministic midpoint by default. */
export function containerSpring(
  kind: ContainerMotion,
  random = () => 0.5,
): SpringOptions {
  if (kind === "dropGather" || kind === "dropSink") {
    const mass =
      (kind === "dropGather"
        ? 0.24 + 0.08 * random()
        : 0.16 + 0.16 * random()) * 0.48;
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "unfold")
    return { stiffness: 240, damping: 20, mass: 0.8 + 0.16 * random() };
  if (kind === "refold") {
    const mass = 0.12 + 0.12 * random();
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "pullReturn")
    return { stiffness: 400, damping: 24, mass: (0.8 + 0.4 * random()) * 0.64 };
  if (kind === "lidOpen") return { stiffness: 100, damping: 10, mass: 0.64 };
  return { stiffness: 100, damping: 2 * Math.sqrt(100 * 0.32), mass: 0.32 };
}

/** Legacy document/image presentation profile: critically damped, softer opening. */
export function presentationSpring(opening: boolean): SpringOptions {
  const mass = opening ? 0.48 : 0.32;
  return { stiffness: 100, mass, damping: 2 * Math.sqrt(100 * mass) };
}

@import "./surface.css";
.roc-page-book {
  width: 100%;
  color: var(--roc-ink);
}
.roc-book-stage {
  height: calc(var(--book-h) + 18px);
  display: grid;
  place-items: center;
  touch-action: pan-y;
  user-select: none;
  cursor: grab;
  perspective: 1800px;
}
.roc-book {
  position: relative;
  width: calc(var(--book-w) * 2);
  height: var(--book-h);
  transform-style: preserve-3d;
}
.roc-page-book[data-mode="single"] .roc-book {
  width: var(--book-w);
}
.roc-book-leaf {
  position: absolute;
  inset: 0 0 0 50%;
  transform-origin: 0 50%;
  transform-style: preserve-3d;
}
.roc-page-book[data-mode="single"] .roc-book-leaf {
  left: 0;
}
.roc-book-face {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: var(--roc-paper, #fcfbf8);
  border: 1px solid var(--roc-line);
  border-radius: 3px;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  padding: 22px;
  box-sizing: border-box;
  font:
    13px/1.7 Georgia,
    serif;
  box-shadow: 0 5px 15px #1f251b0e;
}
.roc-book-face.back {
  transform: rotateY(180deg);
}
.roc-page-book[data-mode="single"] .roc-book-face.back {
  display: none;
}
.roc-book-face.cover {
  background: var(--book-color);
  color: #f4f1ea;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border: 0;
  padding: 25px;
  box-shadow: inset 6px 0 #00000012;
}
.roc-book-face h3 {
  font:
    normal 25px/1.2 Georgia,
    serif;
}
.roc-book-face small {
  font: 9px/1.5 system-ui;
  letter-spacing: 0.06em;
}
.roc-book-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: #1f1e1b;
  opacity: 0;
  z-index: 3;
}
.roc-book-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin-top: 12px;
  font: 11px system-ui;
}
.roc-book-controls button {
  border: 0;
  background: #ffffffa0;
  border-radius: 50%;
  corner-shape: round;
  width: 32px;
  height: 32px;
}
.roc-book-controls button:disabled {
  opacity: 0.3;
}

